inline std::string Identity(const Key&k){return std::to_string(static_cast<int>(k.kind))+":"+std::to_string(k.id)+":"+k.name;}
inline const J& Field(const J&j,const char*lower,const char*upper){return j.contains(lower)?j.at(lower):j.at(upper);}
inline double Finite(const J&j){if(!j.is_number())throw std::runtime_error("facial non-number");double n=j.get<double>();if(!std::isfinite(n))throw std::runtime_error("facial non-finite");return n;}
inline J ParseFacial(const std::vector<char>&bytes){return J::parse(bytes,[](int depth,J::parse_event_t,J&){if(depth>32)throw std::runtime_error("facial JSON depth limit");return true;});}
