 static std::shared_ptr<const std::vector<CurvePoint>> Curve(const J&points,double duration){if(!points.is_array()||points.empty()||points.size()>2048)throw std::runtime_error("strength curve schema/size");auto result=std::make_shared<std::vector<CurvePoint>>();double last=-1;for(auto&p:points){double time=Finite(Field(p,"time","Time")),value=Finite(Field(p,"value","Value"));auto interpolation=Field(p,"interpolation","Interpolation").get<std::string>();if(time<0||time>duration+.000001||time<=last||value<0||value>1||(interpolation!="Linear"&&interpolation!="Hold"))throw std::runtime_error("strength curve bounds/order");result->push_back({time,value,interpolation=="Hold"});last=time;}return result;}
