      J segment={{"id",r.at("id").get<std::string>()+"-"+std::to_string(i)+"-"+std::to_string(part)},{"channel",channel},{"profile",profile},{"start",l},{"end",h},{"gain",r.at("gain")},{"fadeIn",r.at("fadeIn")},{"fadeOut",r.at("fadeOut")},{"envelopeOffset",Finite(r.at("envelopeOffset"))+l-begin},{"sourceDuration",r.at("sourceDuration")},{"priority",priority},{"morphs",morphs}};if(curveSchema&&r.contains("strengthCurve")&&!r.at("strengthCurve").is_null())segment["curveIndex"]=r.at("id");if(flat["segments"].size()>=4096)throw std::runtime_error("compiled facial segment limit");flat["segments"].push_back(std::move(segment));
